// offset_hours > 0 = reminder fires that many hours BEFORE the appointment
// (e.g. 24 = day-before, 2 = hours-before). offset_hours <= 0 = fires
// |offset_hours| AFTER the appointment time (no-show follow-up).
const row = $input.item.json;
const dueAt = new Date(row.due_at).getTime() - row.offset_hours * 3600000;
const now = Date.now();
const catchWindowMs = 6 * 3600000; // tolerate up to 6h of engine downtime without skipping a reminder
const due = now >= dueAt && now < dueAt + catchWindowMs;

function fill(template) {
  const apptDate = new Date(row.due_at).toLocaleString('en-US', { dateStyle: 'full', timeStyle: 'short' });
  return (template || '')
    .replace(/{{\s*first_name\s*}}/gi, row.first_name || 'there')
    .replace(/{{\s*last_name\s*}}/gi, row.last_name || '')
    .replace(/{{\s*appointment_date\s*}}/gi, apptDate)
    .replace(/{{\s*deal_name\s*}}/gi, row.opportunity_name || '');
}

return [{
  json: {
    due,
    stepId: row.step_id,
    opportunityId: row.opportunity_id,
    activityId: row.activity_id,
    to: row.email,
    subject: fill(row.email_subject),
    body: fill(row.email_body),
  },
}];

const row = $input.item.json;

function fill(template) {
  return (template || '')
    .replace(/{{\s*first_name\s*}}/gi, row.first_name || 'there')
    .replace(/{{\s*last_name\s*}}/gi, row.last_name || '')
    .replace(/{{\s*deal_name\s*}}/gi, row.opportunity_name || '');
}

return [{
  json: {
    hasEmail: !!(row.on_complete_email_subject && row.on_complete_email_subject.trim()),
    to: row.email,
    subject: fill(row.on_complete_email_subject),
    body: fill(row.on_complete_email_body),
    onCompleteAdvanceStageId: row.on_complete_advance_stage_id,
    opportunityId: row.opportunity_id,
    ruleId: row.rule_id,
    activityId: row.activity_id,
    contactId: row.contact_id,
  },
}];
